50	namespace aria2 {
51	
52	const char HandshakeExtensionMessage::EXTENSION_NAME[] = "handshake";
53	
54	HandshakeExtensionMessage::HandshakeExtensionMessage()
55	    : tcpPort_{0}, metadataSize_{0}, dctx_{nullptr}
56	{
57	}
58	
59	std::string HandshakeExtensionMessage::getPayload()
60	{
61	  Dict dict;
62	  if (!clientVersion_.empty()) {
63	    dict.put("v", clientVersion_);
64	  }
65	  if (tcpPort_ > 0) {
66	    dict.put("p", Integer::g(tcpPort_));
67	  }
68	  auto extDict = Dict::g();
69	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
70	    int id = extreg_.getExtensionMessageID(i);
71	    if (id) {
72	      extDict->put(strBtExtension(i), Integer::g(id));
73	    }
74	  }
75	  dict.put("m", std::move(extDict));
76	  if (metadataSize_) {
77	    dict.put("metadata_size", Integer::g(metadataSize_));
78	  }
79	  return bencode2::encode(&dict);
80	}
81	
82	std::string HandshakeExtensionMessage::toString() const
83	{
84	  std::string s(fmt("%s client=%s, tcpPort=%u, metadataSize=%lu",
85	                    getExtensionName(),
86	                    util::percentEncode(clientVersion_).c_str(), tcpPort_,
87	                    static_cast<unsigned long>(metadataSize_)));
88	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
89	    int id = extreg_.getExtensionMessageID(i);
90	    if (id) {
91	      s += fmt(", %s=%u", strBtExtension(i), id);
92	    }
93	  }
94	  return s;
95	}
96	
97	void HandshakeExtensionMessage::doReceivedAction()
98	{
99	  if (tcpPort_ > 0) {
100	    peer_->setPort(tcpPort_);
101	    peer_->setIncomingPeer(false);
102	  }
103	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
104	    int id = extreg_.getExtensionMessageID(i);
105	    if (id) {
106	      peer_->setExtension(i, id);
107	    }
108	  }
109	  auto attrs = bittorrent::getTorrentAttrs(dctx_);
110	  if (attrs->metadata.empty()) {
111	    if (!peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_METADATA)) {
112	      // TODO In metadataGetMode, if peer don't support metadata
113	      // transfer, should we drop connection? There is a possibility
114	      // that peer can still tell us peers using PEX.
115	      throw DL_ABORT_EX("Peer doesn't support ut_metadata extension. Goodbye.");
116	    }
117	    if (metadataSize_ > 0) {
118	      if (attrs->metadataSize) {
119	        if (metadataSize_ != attrs->metadataSize) {
120	          throw DL_ABORT_EX("Wrong metadata_size. Which one is correct!?");
121	        }
122	      }
123	      else {
124	        attrs->metadataSize = metadataSize_;
125	        dctx_->getFirstFileEntry()->setLength(metadataSize_);
126	        dctx_->markTotalLengthIsKnown();
127	        dctx_->getOwnerRequestGroup()->initPieceStorage();
128	        // We enter 'end game' mode from the start to get metadata
129	        // quickly.
130	        dctx_->getOwnerRequestGroup()->getPieceStorage()->enterEndGame();
131	      }
132	      peer_->reconfigureSessionResource(dctx_->getPieceLength(),
133	                                        dctx_->getTotalLength());
134	      peer_->setAllBitfield();
135	    }
136	    else {
137	      throw DL_ABORT_EX("Peer didn't provide metadata_size."
138	                        " It seems that it doesn't have whole metadata.");
139	    }
140	  }
141	}
142	
143	void HandshakeExtensionMessage::setPeer(const std::shared_ptr<Peer>& peer)
144	{
145	  peer_ = peer;
146	}
147	
148	void HandshakeExtensionMessage::setExtension(int key, uint8_t id)
149	{
150	  extreg_.setExtensionMessageID(key, id);
151	}
152	
153	void HandshakeExtensionMessage::setExtensions(const Extensions& extensions)
154	{
155	  extreg_.setExtensions(extensions);
156	}
157	
158	uint8_t HandshakeExtensionMessage::getExtensionMessageID(int key) const
159	{
160	  return extreg_.getExtensionMessageID(key);
161	}
162	
163	std::unique_ptr<HandshakeExtensionMessage>
164	HandshakeExtensionMessage::create(const unsigned char* data, size_t length)
165	{
166	  if (length < 1) {
167	    throw DL_ABORT_EX(fmt(MSG_TOO_SMALL_PAYLOAD_SIZE, EXTENSION_NAME,
168	                          static_cast<unsigned long>(length)));
169	  }
170	  A2_LOG_DEBUG(fmt("Creating HandshakeExtensionMessage from %s",
171	                   util::percentEncode(data, length).c_str()));
172	  auto decoded = bencode2::decode(data + 1, length - 1);
173	  const Dict* dict = downcast<Dict>(decoded);
174	  if (!dict) {
175	    throw DL_ABORT_EX(
176	        "Unexpected payload format for extended message handshake");
177	  }
178	  auto msg = make_unique<HandshakeExtensionMessage>();
179	  const Integer* port = downcast<Integer>(dict->get("p"));
180	  if (port && 0 < port->i() && port->i() < 65536) {
181	    msg->tcpPort_ = port->i();
182	  }
183	  const String* version = downcast<String>(dict->get("v"));
184	  if (version) {
185	    msg->clientVersion_ = version->s();
186	  }
187	  const Dict* extDict = downcast<Dict>(dict->get("m"));
188	  if (extDict) {
189	    for (auto& elem : *extDict) {
190	      const Integer* extId = downcast<Integer>(elem.second);
191	      if (extId) {
192	        if (extId->i() < 0 || extId->i() > 255) {
193	          A2_LOG_DEBUG(fmt("Extension ID=%" PRId64 " is invalid", extId->i()));
194	          continue;
195	        }
196	
197	        int key = keyBtExtension(elem.first.c_str());
198	        if (key == ExtensionMessageRegistry::MAX_EXTENSION) {
199	          A2_LOG_DEBUG(fmt("Unsupported BitTorrent extension %s=%" PRId64,
200	                           elem.first.c_str(), extId->i()));
201	        }
202	        else {
203	          msg->setExtension(key, extId->i());
204	        }
205	      }
206	    }
207	  }
208	  const Integer* metadataSize = downcast<Integer>(dict->get("metadata_size"));
209	
210	  if (metadataSize) {
211	    auto size = metadataSize->i();
212	
213	    if (size < 0) {
214	      throw DL_ABORT_EX(
215	          fmt("Negative metadataSize %" PRId64 " was received", size));
216	    }
217	
218	    // Only accept metadata up to 8MiB in size.  Be aware that broken
219	    // client can send negative size!
220	    if (size > 0 && size <= static_cast<int64_t>(8_m)) {
221	      msg->metadataSize_ = size;
222	    }
223	  }
224	  return msg;
225	}
226	
227	} // namespace aria2
