59	std::string HandshakeExtensionMessage::getPayload()
60	{
61	  Dict dict;
62	  if (!clientVersion_.empty()) {
63	    dict.put("v", clientVersion_);
64	  }
65	  if (tcpPort_ > 0) {
66	    dict.put("p", Integer::g(tcpPort_));
67	  }
68	  auto extDict = Dict::g();
69	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
70	    int id = extreg_.getExtensionMessageID(i);
71	    if (id) {
72	      extDict->put(strBtExtension(i), Integer::g(id));
73	    }
74	  }
75	  dict.put("m", std::move(extDict));
76	  if (metadataSize_) {
77	    dict.put("metadata_size", Integer::g(metadataSize_));
78	  }
79	  return bencode2::encode(&dict);
80	}
81	
82	std::string HandshakeExtensionMessage::toString() const
83	{
84	  std::string s(fmt("%s client=%s, tcpPort=%u, metadataSize=%lu",
85	                    getExtensionName(),
86	                    util::percentEncode(clientVersion_).c_str(), tcpPort_,
87	                    static_cast<unsigned long>(metadataSize_)));
88	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
89	    int id = extreg_.getExtensionMessageID(i);
90	    if (id) {
91	      s += fmt(", %s=%u", strBtExtension(i), id);
92	    }
93	  }
94	  return s;
95	}
96	
97	void HandshakeExtensionMessage::doReceivedAction()
98	{
99	  if (tcpPort_ > 0) {
100	    peer_->setPort(tcpPort_);
101	    peer_->setIncomingPeer(false);
102	  }
103	  for (int i = 0; i < ExtensionMessageRegistry::MAX_EXTENSION; ++i) {
104	    int id = extreg_.getExtensionMessageID(i);
105	    if (id) {
106	      peer_->setExtension(i, id);
107	    }
108	  }
109	  auto attrs = bittorrent::getTorrentAttrs(dctx_);
110	  if (attrs->metadata.empty()) {
111	    if (!peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_METADATA)) {
112	      // TODO In metadataGetMode, if peer don't support metadata
113	      // transfer, should we drop connection? There is a possibility
114	      // that peer can still tell us peers using PEX.
115	      throw DL_ABORT_EX("Peer doesn't support ut_metadata extension. Goodbye.");
116	    }
117	    if (metadataSize_ > 0) {
118	      if (attrs->metadataSize) {
119	        if (metadataSize_ != attrs->metadataSize) {
120	          throw DL_ABORT_EX("Wrong metadata_size. Which one is correct!?");
121	        }
122	      }
123	      else {
124	        attrs->metadataSize = metadataSize_;
125	        dctx_->getFirstFileEntry()->setLength(metadataSize_);
126	        dctx_->markTotalLengthIsKnown();
127	        dctx_->getOwnerRequestGroup()->initPieceStorage();
128	        // We enter 'end game' mode from the start to get metadata
129	        // quickly.
130	        dctx_->getOwnerRequestGroup()->getPieceStorage()->enterEndGame();
131	      }
132	      peer_->reconfigureSessionResource(dctx_->getPieceLength(),
133	                                        dctx_->getTotalLength());
134	      peer_->setAllBitfield();
135	    }
136	    else {
137	      throw DL_ABORT_EX("Peer didn't provide metadata_size."
138	                        " It seems that it doesn't have whole metadata.");
139	    }
140	  }
141	}
