163	std::unique_ptr<HandshakeExtensionMessage>
164	HandshakeExtensionMessage::create(const unsigned char* data, size_t length)
165	{
166	  if (length < 1) {
167	    throw DL_ABORT_EX(fmt(MSG_TOO_SMALL_PAYLOAD_SIZE, EXTENSION_NAME,
168	                          static_cast<unsigned long>(length)));
169	  }
170	  A2_LOG_DEBUG(fmt("Creating HandshakeExtensionMessage from %s",
171	                   util::percentEncode(data, length).c_str()));
172	  auto decoded = bencode2::decode(data + 1, length - 1);
173	  const Dict* dict = downcast<Dict>(decoded);
174	  if (!dict) {
175	    throw DL_ABORT_EX(
176	        "Unexpected payload format for extended message handshake");
177	  }
178	  auto msg = make_unique<HandshakeExtensionMessage>();
179	  const Integer* port = downcast<Integer>(dict->get("p"));
180	  if (port && 0 < port->i() && port->i() < 65536) {
181	    msg->tcpPort_ = port->i();
182	  }
183	  const String* version = downcast<String>(dict->get("v"));
184	  if (version) {
185	    msg->clientVersion_ = version->s();
186	  }
187	  const Dict* extDict = downcast<Dict>(dict->get("m"));
188	  if (extDict) {
189	    for (auto& elem : *extDict) {
190	      const Integer* extId = downcast<Integer>(elem.second);
191	      if (extId) {
192	        if (extId->i() < 0 || extId->i() > 255) {
193	          A2_LOG_DEBUG(fmt("Extension ID=%" PRId64 " is invalid", extId->i()));
194	          continue;
195	        }
196	
197	        int key = keyBtExtension(elem.first.c_str());
198	        if (key == ExtensionMessageRegistry::MAX_EXTENSION) {
199	          A2_LOG_DEBUG(fmt("Unsupported BitTorrent extension %s=%" PRId64,
200	                           elem.first.c_str(), extId->i()));
201	        }
202	        else {
203	          msg->setExtension(key, extId->i());
204	        }
205	      }
206	    }
207	  }
208	  const Integer* metadataSize = downcast<Integer>(dict->get("metadata_size"));
209	
210	  if (metadataSize) {
211	    auto size = metadataSize->i();
212	
213	    if (size < 0) {
214	      throw DL_ABORT_EX(
215	          fmt("Negative metadataSize %" PRId64 " was received", size));
216	    }
217	
218	    // Only accept metadata up to 8MiB in size.  Be aware that broken
219	    // client can send negative size!
220	    if (size > 0 && size <= static_cast<int64_t>(8_m)) {
221	      msg->metadataSize_ = size;
222	    }
223	  }
224	  return msg;
225	}
