namespace aria2 {

const char BtExtendedMessage::NAME[] = "extended";

BtExtendedMessage::BtExtendedMessage(
    std::unique_ptr<ExtensionMessage> extensionMessage)
    : SimpleBtMessage(ID, NAME),
      extensionMessage_(std::move(extensionMessage)),
      msgLength_(0)
