std::vector<unsigned char> BtExtendedMessage::createMessage()
{
  /**
   * len --- 2+extpayload.length, 4bytes
   * id --- 20, 1byte
   * extmsgid --- extmsgid, 1byte
   * extpayload --- extpayload, nbytes
