52	
53	BtExtendedMessage::BtExtendedMessage(
54	    std::unique_ptr<ExtensionMessage> extensionMessage)
55	    : SimpleBtMessage(ID, NAME),
56	      extensionMessage_(std::move(extensionMessage)),
57	      msgLength_(0)
58	{
59	}
60	
61	std::vector<unsigned char> BtExtendedMessage::createMessage()
62	{
63	  /**
64	   * len --- 2+extpayload.length, 4bytes
65	   * id --- 20, 1byte
66	   * extmsgid --- extmsgid, 1byte
67	   * extpayload --- extpayload, nbytes
68	   * total: 6+extpayload.length bytes
69	   */
70	  std::string payload = extensionMessage_->getPayload();
71	  msgLength_ = 6 + payload.size();
72	  auto msg = std::vector<unsigned char>(msgLength_);
73	  auto p = msg.data();
74	  bittorrent::createPeerMessageString(p, msgLength_, 2 + payload.size(), ID);
75	  p += 5;
76	  *p++ = extensionMessage_->getExtensionMessageID();
77	  std::copy(std::begin(payload), std::end(payload), p);
78	  return msg;
79	}
80	
81	bool BtExtendedMessage::sendPredicate() const
82	{
83	  return getPeer()->isExtendedMessagingEnabled();
84	}
