86	std::string BtExtendedMessage::toString() const
87	{
88	  std::string s = NAME;
89	  s += " ";
90	  s += extensionMessage_->toString();
91	  return s;
92	}
93	
94	std::unique_ptr<BtExtendedMessage>
95	BtExtendedMessage::create(ExtensionMessageFactory* factory,
96	                          const std::shared_ptr<Peer>& peer,
97	                          const unsigned char* data, size_t dataLength)
98	{
99	  bittorrent::assertPayloadLengthGreater(1, dataLength, NAME);
100	  bittorrent::assertID(ID, data, NAME);
101	  assert(factory);
102	  return make_unique<BtExtendedMessage>(
103	      factory->createMessage(data + 1, dataLength - 1));
104	}
