36	#include "Peer.h"
37	#include "util.h"
38	#include "bittorrent_helper.h"
39	#include "PeerStorage.h"
40	#include "DlAbortEx.h"
41	#include "message.h"
42	#include "fmt.h"
43	#include "bencode2.h"
44	#include "a2functional.h"
45	#include "wallclock.h"
46	
47	namespace aria2 {
48	
49	namespace {
50	
51	// This is the hard limit of the number of "fresh peer" and "dropped
52	// peer".  This number is treated as the sum of IPv4 and IPv6 peers.
53	const size_t DEFAULT_MAX_FRESH_PEER = 50;
54	const size_t DEFAULT_MAX_DROPPED_PEER = 50;
55	
56	} // namespace
57	
58	const char UTPexExtensionMessage::EXTENSION_NAME[] = "ut_pex";
59	
60	constexpr std::chrono::minutes UTPexExtensionMessage::DEFAULT_INTERVAL;
61	
62	UTPexExtensionMessage::UTPexExtensionMessage(uint8_t extensionMessageID)
63	    : extensionMessageID_{extensionMessageID},
64	      peerStorage_{nullptr},
65	      interval_{DEFAULT_INTERVAL},
66	      maxFreshPeer_{DEFAULT_MAX_FRESH_PEER},
67	      maxDroppedPeer_{DEFAULT_MAX_DROPPED_PEER}
68	{
69	}
70	
71	std::string UTPexExtensionMessage::getPayload()
72	{
73	  auto freshPeerPair = createCompactPeerListAndFlag(freshPeers_);
74	  auto droppedPeerPair = createCompactPeerListAndFlag(droppedPeers_);
75	  Dict dict;
76	  if (!freshPeerPair.first.first.empty()) {
77	    dict.put("added", freshPeerPair.first.first);
78	    dict.put("added.f", freshPeerPair.first.second);
79	  }
80	  if (!droppedPeerPair.first.first.empty()) {
81	    dict.put("dropped", droppedPeerPair.first.first);
82	  }
83	  if (!freshPeerPair.second.first.empty()) {
84	    dict.put("added6", freshPeerPair.second.first);
85	    dict.put("added6.f", freshPeerPair.second.second);
86	  }
87	  if (!droppedPeerPair.second.first.empty()) {
88	    dict.put("dropped6", droppedPeerPair.second.first);
89	  }
90	
91	  return bencode2::encode(&dict);
92	}
93	
94	std::pair<std::pair<std::string, std::string>,
95	          std::pair<std::string, std::string>>
96	UTPexExtensionMessage::createCompactPeerListAndFlag(
97	    const std::vector<std::shared_ptr<Peer>>& peers)
98	{
99	  std::string addrstring;
100	  std::string flagstring;
101	  std::string addrstring6;
102	  std::string flagstring6;
103	  for (auto itr = std::begin(peers), eoi = std::end(peers); itr != eoi; ++itr) {
104	    unsigned char compact[COMPACT_LEN_IPV6];
105	    int compactlen = bittorrent::packcompact(compact, (*itr)->getIPAddress(),
106	                                             (*itr)->getPort());
107	    if (compactlen == COMPACT_LEN_IPV4) {
108	      addrstring.append(&compact[0], &compact[compactlen]);
109	      flagstring += (*itr)->isSeeder() ? 0x02u : 0x00u;
110	    }
111	    else if (compactlen == COMPACT_LEN_IPV6) {
112	      addrstring6.append(&compact[0], &compact[compactlen]);
113	      flagstring6 += (*itr)->isSeeder() ? 0x02u : 0x00u;
114	    }
115	  }
116	  return std::make_pair(
117	      std::make_pair(std::move(addrstring), std::move(flagstring)),
118	      std::make_pair(std::move(addrstring6), std::move(flagstring6)));
119	}
120	
121	std::string UTPexExtensionMessage::toString() const
122	{
123	  return fmt("ut_pex added=%lu, dropped=%lu",
124	             static_cast<unsigned long>(freshPeers_.size()),
125	             static_cast<unsigned long>(droppedPeers_.size()));
126	}
127	
128	void UTPexExtensionMessage::doReceivedAction()
129	{
130	  peerStorage_->addPeer(freshPeers_);
131	  peerStorage_->addPeer(droppedPeers_);
132	}
133	
134	bool UTPexExtensionMessage::addFreshPeer(const std::shared_ptr<Peer>& peer)
135	{
136	  if (!peer->isIncomingPeer() &&
137	      peer->getFirstContactTime().difference(global::wallclock()) < interval_) {
138	    freshPeers_.push_back(peer);
139	    return true;
140	  }
141	  else {
142	    return false;
143	  }
144	}
145	
146	const std::vector<std::shared_ptr<Peer>>&
147	UTPexExtensionMessage::getFreshPeers() const
148	{
149	  return freshPeers_;
150	}
151	
152	bool UTPexExtensionMessage::freshPeersAreFull() const
153	{
154	  return freshPeers_.size() >= maxFreshPeer_;
155	}
156	
157	bool UTPexExtensionMessage::addDroppedPeer(const std::shared_ptr<Peer>& peer)
158	{
159	  if (!peer->isIncomingPeer() &&
160	      peer->getDropStartTime().difference(global::wallclock()) < interval_) {
161	    droppedPeers_.push_back(peer);
162	    return true;
163	  }
164	  else {
165	    return false;
166	  }
167	}
168	
169	const std::vector<std::shared_ptr<Peer>>&
170	UTPexExtensionMessage::getDroppedPeers() const
171	{
172	  return droppedPeers_;
173	}
174	
175	bool UTPexExtensionMessage::droppedPeersAreFull() const
176	{
177	  return droppedPeers_.size() >= maxDroppedPeer_;
178	}
179	
180	void UTPexExtensionMessage::setMaxFreshPeer(size_t maxFreshPeer)
181	{
182	  maxFreshPeer_ = maxFreshPeer;
183	}
184	
185	void UTPexExtensionMessage::setMaxDroppedPeer(size_t maxDroppedPeer)
186	{
187	  maxDroppedPeer_ = maxDroppedPeer;
188	}
189	
190	void UTPexExtensionMessage::setPeerStorage(PeerStorage* peerStorage)
191	{
192	  peerStorage_ = peerStorage;
193	}
194	
195	std::unique_ptr<UTPexExtensionMessage>
196	UTPexExtensionMessage::create(const unsigned char* data, size_t len)
197	{
198	  if (len < 1) {
199	    throw DL_ABORT_EX(fmt(MSG_TOO_SMALL_PAYLOAD_SIZE, EXTENSION_NAME,
200	                          static_cast<unsigned long>(len)));
201	  }
202	  auto msg = make_unique<UTPexExtensionMessage>(*data);
203	
204	  auto decoded = bencode2::decode(data + 1, len - 1);
205	  const Dict* dict = downcast<Dict>(decoded);
206	  if (dict) {
207	    const String* added = downcast<String>(dict->get("added"));
208	    if (added) {
209	      bittorrent::extractPeer(added, AF_INET,
210	                              std::back_inserter(msg->freshPeers_));
211	    }
212	    const String* dropped = downcast<String>(dict->get("dropped"));
213	    if (dropped) {
214	      bittorrent::extractPeer(dropped, AF_INET,
215	                              std::back_inserter(msg->droppedPeers_));
216	    }
217	    const String* added6 = downcast<String>(dict->get("added6"));
218	    if (added6) {
219	      bittorrent::extractPeer(added6, AF_INET6,
220	                              std::back_inserter(msg->freshPeers_));
221	    }
222	    const String* dropped6 = downcast<String>(dict->get("dropped6"));
223	    if (dropped6) {
224	      bittorrent::extractPeer(dropped6, AF_INET6,
225	                              std::back_inserter(msg->droppedPeers_));
226	    }
227	  }
228	  return msg;
229	}
230	
231	} // namespace aria2
