65	std::string UTMetadataRequestExtensionMessage::getPayload()
66	{
67	  Dict dict;
68	  dict.put("msg_type", Integer::g(0));
69	  dict.put("piece", Integer::g(getIndex()));
70	  return bencode2::encode(&dict);
