79	void UTMetadataRequestExtensionMessage::doReceivedAction()
80	{
81	  auto attrs = bittorrent::getTorrentAttrs(dctx_);
82	  uint8_t id =
83	      peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_METADATA);
84	  if (attrs->metadata.empty()) {
85	    auto m = make_unique<UTMetadataRejectExtensionMessage>(id);
86	    m->setIndex(getIndex());
87	    dispatcher_->addMessageToQueue(
88	        messageFactory_->createBtExtendedMessage(std::move(m)));
89	  }
90	  else if (getIndex() * METADATA_PIECE_SIZE < attrs->metadataSize) {
91	    auto m = make_unique<UTMetadataDataExtensionMessage>(id);
92	    m->setIndex(getIndex());
93	    m->setTotalSize(attrs->metadataSize);
94	    auto begin = std::begin(attrs->metadata) + getIndex() * METADATA_PIECE_SIZE;
95	    auto end = (getIndex() + 1) * METADATA_PIECE_SIZE <= attrs->metadata.size()
96	                   ? std::begin(attrs->metadata) +
97	                         (getIndex() + 1) * METADATA_PIECE_SIZE
98	                   : std::end(attrs->metadata);
99	    m->setData(begin, end);
100	    dispatcher_->addMessageToQueue(
101	        messageFactory_->createBtExtendedMessage(std::move(m)));
102	  }
103	  else {
104	    throw DL_ABORT_EX(fmt("Metadata piece index is too big. piece=%lu",
105	                          static_cast<unsigned long>(getIndex())));
106	  }
107	}
