61	DefaultExtensionMessageFactory::DefaultExtensionMessageFactory()
62	    : peerStorage_{nullptr},
63	      registry_{nullptr},
64	      dctx_{nullptr},
65	      messageFactory_{nullptr},
66	      dispatcher_{nullptr},
67	      tracker_{nullptr}
68	{
69	}
70	
71	DefaultExtensionMessageFactory::DefaultExtensionMessageFactory(
72	    const std::shared_ptr<Peer>& peer, ExtensionMessageRegistry* registry)
73	    : peerStorage_{nullptr},
74	      peer_{peer},
75	      registry_{registry},
76	      dctx_{nullptr},
77	      messageFactory_{nullptr},
78	      dispatcher_{nullptr},
79	      tracker_{nullptr}
80	{
81	}
82	
83	std::unique_ptr<ExtensionMessage>
84	DefaultExtensionMessageFactory::createMessage(const unsigned char* data,
85	                                              size_t length)
86	{
87	  uint8_t extensionMessageID = *data;
88	  if (extensionMessageID == 0) {
89	    // handshake
90	    auto m = HandshakeExtensionMessage::create(data, length);
91	    m->setPeer(peer_);
92	    m->setDownloadContext(dctx_);
93	    return std::move(m);
94	  }
95	  else {
96	    const char* extensionName = registry_->getExtensionName(extensionMessageID);
97	    if (!extensionName) {
98	      throw DL_ABORT_EX(
99	          fmt("No extension registered for extended message ID %u",
100	              extensionMessageID));
101	    }
102	    if (strcmp(extensionName, "ut_pex") == 0) {
103	      // uTorrent compatible Peer-Exchange
104	      auto m = UTPexExtensionMessage::create(data, length);
105	      m->setPeerStorage(peerStorage_);
106	      return std::move(m);
107	    }
108	    else if (strcmp(extensionName, "ut_metadata") == 0) {
109	      if (length == 0) {
110	        throw DL_ABORT_EX(fmt(MSG_TOO_SMALL_PAYLOAD_SIZE, "ut_metadata",
111	                              static_cast<unsigned long>(length)));
112	      }
113	      size_t end;
114	      auto decoded = bencode2::decode(data + 1, length - 1, end);
115	      const Dict* dict = downcast<Dict>(decoded);
116	      if (!dict) {
117	        throw DL_ABORT_EX("Bad ut_metadata: dictionary not found");
118	      }
119	      const Integer* msgType = downcast<Integer>(dict->get("msg_type"));
120	      if (!msgType) {
121	        throw DL_ABORT_EX("Bad ut_metadata: msg_type not found");
122	      }
123	      const Integer* index = downcast<Integer>(dict->get("piece"));
124	      if (!index || index->i() < 0) {
125	        throw DL_ABORT_EX("Bad ut_metadata: piece not found");
126	      }
127	      switch (msgType->i()) {
128	      case 0: {
129	        auto m =
130	            make_unique<UTMetadataRequestExtensionMessage>(extensionMessageID);
131	        m->setIndex(index->i());
132	        m->setDownloadContext(dctx_);
133	        m->setPeer(peer_);
134	        m->setBtMessageFactory(messageFactory_);
135	        m->setBtMessageDispatcher(dispatcher_);
136	        return std::move(m);
137	      }
138	      case 1: {
139	        if (end == length) {
140	          throw DL_ABORT_EX("Bad ut_metadata data: data not found");
141	        }
142	        const Integer* totalSize = downcast<Integer>(dict->get("total_size"));
143	        if (!totalSize || totalSize->i() < 0) {
144	          throw DL_ABORT_EX("Bad ut_metadata data: total_size not found");
145	        }
146	        auto m =
147	            make_unique<UTMetadataDataExtensionMessage>(extensionMessageID);
148	        m->setIndex(index->i());
149	        m->setTotalSize(totalSize->i());
150	        m->setData(&data[1 + end], &data[length]);
151	        m->setUTMetadataRequestTracker(tracker_);
152	        m->setPieceStorage(
153	            dctx_->getOwnerRequestGroup()->getPieceStorage().get());
154	        m->setDownloadContext(dctx_);
